18	import type { EnchantmentId, Recipe } from "@/lib/game/types";
19	import { type WorldMeta, worldSaveKey } from "@/lib/game/worlds";
20	
21	/**
22	 * Thin React shell around the headless GameEngine and the GameRenderer.
23	 *
24	 * The engine is created in the canvas mount's callback ref (commit phase) and
25	 * held in React state; the UI reads it through useSyncExternalStore snapshots
26	 * and sends intents back as engine commands. The effect below owns everything
27	 * with a lifecycle: renderer, input listeners, the rAF loop, and autosave.
28	 */
29	
30	// Pre-mount snapshot (also the SSR snapshot): the starter loadout at full stats.
31	const PRE_MOUNT_SNAPSHOT: GameSnapshot = {
32	  api: null,
33	  inventory: createInitialInventory(),
34	  equippedArmor: createEmptyArmorEquipment(),
35	  selectedSlot: 0,
36	  hearts: MAX_HEARTS,
37	  hunger: MAX_HUNGER,
38	  oxygen: MAX_OXYGEN,
39	  daylightPercent: 100,
40	  passiveCount: 0,
41	  hostileCount: 0,
42	  respawnSeconds: 0,
43	  inventoryOpen: false,
44	  paused: false,
45	  debugOpen: false,
46	  debug: null,
47	  cameraMode: "first",
48	  armorPoints: 0,
49	  capsActive: false,
50	  sleeping: false,
51	  craftingStation: null,
52	  container: null,
53	  boss: null,
54	  victory: false,
55	  activeEffects: [],
56	  xpLevel: 0,
57	  xpProgress: 0
58	};
59	
60	const noopSubscribe = () => () => {};
61	
62	type GameContext = { engine: GameEngine; node: HTMLDivElement };
63	
64	// Debug/test handle: lets the browser console and the Playwright E2E suite
65	// inspect the live simulation (single-player client game — nothing to protect).
66	declare global {
67	  interface Window {
68	    __monecraft?: { engine: GameEngine; renderer: GameRenderer; input: InputController; audio: AudioDirector };
69	  }
70	}
71	
72	function persistGame(api: GameApi, saveKey: string, onMessage: (text: string) => void): void {
73	  try {
74	    writeSave(saveKey, api.serialize());
75	    onMessage("Saved");
76	  } catch {
77	    onMessage("Save failed");
78	  }
79	}
80	
81	/**
82	 * One mounted game = one world played by one profile. The owning shell remounts
83	 * this hook (via a React `key` on the world id) to switch worlds, so the
84	 * per-world save key and the profile are fixed for the hook's lifetime.
85	 */
86	export type UseMinecraftGameOptions = {
87	  world: WorldMeta;
88	  profile: Profile;
89	  /** Leave this world and return to the world list (the shell unmounts us). */
90	  onQuitToWorlds: () => void;
91	  /** Re-read this world from disk by forcing a fresh mount (used by Load/Reset). */
92	  onReloadWorld: () => void;
93	};
94	
95	export function useMinecraftGame(opts: UseMinecraftGameOptions) {
96	  // The owning shell keys this hook by world id, so the world is fixed for the
97	  // mount's life; capturing it once in refs lets the long-lived rAF/autosave
98	  // effect read the save key and seed without re-subscribing.
99	  const saveKeyRef = useRef(worldSaveKey(opts.world.id));
100	  const worldSeedRef = useRef(opts.world.seed);
101	  const worldTypeRef = useRef(opts.world.worldType);
102	  const [ctx, setCtx] = useState<GameContext | null>(null);
103	  const [locked, setLocked] = useState(false);
104	  const [saveMessage, setSaveMessage] = useState("");
105	  const [rendererError, setRendererError] = useState<string | null>(null);
106	  const [audioSettings, setAudioSettings] = useState<AudioSettings>(DEFAULT_AUDIO_SETTINGS);
107	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
108	  const minimapNodeRef = useRef<HTMLDivElement | null>(null);
109	  const audioRef = useRef<AudioDirector | null>(null);
110	  // The rAF effect must not re-run on volume tweaks — it reads through a ref.
111	  const audioSettingsRef = useRef(audioSettings);
112	  const [skinId, setSkinId] = useState<SkinId>(opts.profile.skinId);
113	  const skinIdRef = useRef(skinId);
114	  const rendererRef = useRef<GameRenderer | null>(null);
115	  // Pending UI timers (flash messages, world-reload defers) so they can be
116	  // cancelled on unmount instead of firing setState/onReloadWorld after teardown.
117	  const pendingTimeoutsRef = useRef<Set<number>>(new Set());
118	
119	  // Audio is a global preference loaded after mount: render never touches
120	  // localStorage (SSR), and the setState hops a microtask like the
121	  // renderer-error report. This effect runs before the renderer effect (ctx is
122	  // set by a callback ref in a later commit), so the ref is populated by the
123	  // time either exists. The skin is per-profile and comes in via opts, not here.
124	  useEffect(() => {
125	    const stored = readAudioSettings();
126	    audioSettingsRef.current = stored;
127	    audioRef.current?.setSettings(stored);
128	    queueMicrotask(() => setAudioSettings(stored));
129	  }, []);
130	
131	  const updateAudioSettings = useCallback((partial: Partial<AudioSettings>) => {
132	    const next = { ...audioSettingsRef.current, ...partial };
133	    audioSettingsRef.current = next;
134	    setAudioSettings(next);
135	    writeAudioSettings(next);
136	    audioRef.current?.setSettings(next);
137	  }, []);
138	
139	  const updateSkin = useCallback(
140	    (id: SkinId) => {
141	      skinIdRef.current = id;
142	      setSkinId(id);
143	      setProfileSkin(opts.profile.id, id);
144	      rendererRef.current?.setPlayerSkin(getSkinPreset(id).palette);
145	    },
146	    [opts.profile.id]
147	  );
148	
149	  // Callback ref: the engine boots as soon as the canvas mount exists. A ref
150	  // callback runs during commit, where side effects and setState are legal.
151	  const attachMount = useCallback((node: HTMLDivElement | null) => {
152	    if (!node) {
153	      setCtx(null);
154	      return;
155	    }
156	    // A saved blob carries its own seed + type (engine prefers them); a fresh
157	    // world (no blob yet) boots from the world's stored seed and type.
158	    setCtx({
159	      engine: new GameEngine({ save: readSave(saveKeyRef.current), seed: worldSeedRef.current, worldType: worldTypeRef.current }),
160	      node
161	    });
162	  }, []);
163	
164	  // The minimap container mounts independently of the canvas; the rAF loop
165	  // below picks it up lazily once both exist.
166	  const attachMinimap = useCallback((node: HTMLDivElement | null) => {
167	    minimapNodeRef.current = node;
168	  }, []);
169	
170	  const engine = ctx?.engine ?? null;
171	  const subscribe = useMemo(() => engine?.subscribe ?? noopSubscribe, [engine]);
172	  const getSnapshot = useMemo(() => engine?.getSnapshot ?? (() => PRE_MOUNT_SNAPSHOT), [engine]);
173	  const getServerSnapshot = useCallback(() => PRE_MOUNT_SNAPSHOT, []);
174	  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
175	
176	  // Tracks each timer so unmount can cancel it; the timer also self-removes when
177	  // it fires so the set never grows unbounded.

